// Classifying time complexity examples
function constant(arr) {
  return arr[0]; // O(1)
}

function linear(arr) {
  for (let x of arr) console.log(x); // O(n)
}

function quadratic(arr) {
  for (let i = 0; i < arr.length; i++)
    for (let j = 0; j < arr.length; j++)
      console.log(arr[i], arr[j]); // O(n²)
}

function logarithmic(arr, target) {
  let lo = 0, hi = arr.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (arr[mid] === target) return mid;
    arr[mid] < target ? lo = mid + 1 : hi = mid - 1;
  }
  return -1; // O(log n)
}

