// Dynamic Array with amortized O(1) append
class DynamicArray {
  constructor() {
    this.data = new Array(1);
    this.size = 0;
    this.capacity = 1;
  }

  push(val) {
    if (this.size === this.capacity) {
      // Resize: O(n) but happens rarely
      const newData = new Array(this.capacity * 2);
      for (let i = 0; i < this.size; i++) newData[i] = this.data[i];
      this.data = newData;
      this.capacity *= 2;
    }
    this.data[this.size++] = val; // O(1) amortized
  }

  get(i) { return this.data[i]; } // O(1)
}

