class DynamicArray:
    def __init__(self):
        self._data = [None]  # initial capacity 1
        self._size = 0
        self._capacity = 1

    def push(self, val):
        if self._size == self._capacity:
            # Resize: O(n), but amortized O(1)
            new_data = [None] * (self._capacity * 2)
            for i in range(self._size):
                new_data[i] = self._data[i]
            self._data = new_data
            self._capacity *= 2
        self._data[self._size] = val
        self._size += 1

    def __getitem__(self, i):
        return self._data[i]  # O(1)

