template<typename T>
class DynamicArray {
    T* data;
    int sz = 0, cap = 1;
public:
    DynamicArray() { data = new T[1]; }

    void push(T val) {
        if (sz == cap) {
            T* newData = new T[cap * 2];
            for (int i = 0; i < sz; i++) newData[i] = data[i];
            delete[] data;
            data = newData;
            cap *= 2;
        }
        data[sz++] = val; // O(1) amortized
    }

    T get(int i) { return data[i]; } // O(1)
};

