public class DynamicArray {
    private int[] data;
    private int size = 0, capacity = 1;

    public DynamicArray() { data = new int[1]; }

    public void push(int val) {
        if (size == capacity) {
            // Resize: O(n), amortized O(1)
            int[] newData = new int[capacity * 2];
            System.arraycopy(data, 0, newData, 0, size);
            data = newData;
            capacity *= 2;
        }
        data[size++] = val; // O(1) amortized
    }

    public int get(int i) { return data[i]; } // O(1)
}
